package in.foodcart.data;
import in.foodcart.domain.VendorStatus; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.Indexed; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; import java.util.ArrayList; import java.util.List;
@Document("vendors") public class VendorEntity { @Id public String id; @Indexed(unique=true) public String slug; /** One stall per number; the unique index is made by config/VendorMobileIndex, which checks for duplicates first. */ public String mobile; public String name,description,address,logoUrl,coverImageUrl,themeColor="#102820"; /** StoreThemes key; replaces themeColor (Oct 10). */ public String theme=in.foodcart.service.StoreThemes.DEFAULT; /** Set from the vendor app's location flow; address is the written form shown to customers. */ public VendorLocation location; public VendorStatus status=VendorStatus.OPEN; /** Empty until the vendor sets hours; customers can't pick a slot (or order) until then. */ public List<OpeningHours> openingHours=new ArrayList<>(); /** Category ids in the order the vendor arranged them; see CategoryOrder. */ public List<String> categoryOrder=new ArrayList<>(); /** Onboarding state; missing on older documents, which therefore load as APPROVED. */ public in.foodcart.domain.VendorReview review=in.foodcart.domain.VendorReview.APPROVED; /** The team's note when sending a stall back. */ public String reviewNote; public Instant submittedAt,reviewedAt; /** Plan changes in time order: [{plan, from: "2026-11"}]; empty means DAILY (VendorBilling). */ public List<PlanStep> planSteps=new ArrayList<>(); public static class PlanStep { public in.foodcart.domain.VendorPlan plan; /** First month, "yyyy-MM". */ public String from; public PlanStep(){} public PlanStep(in.foodcart.domain.VendorPlan plan,String from){this.plan=plan;this.from=from;} } public Instant createdAt=Instant.now(),updatedAt=Instant.now(); /** Customers can see and order from this stall. */ public boolean live(){return review==in.foodcart.domain.VendorReview.APPROVED;} }
